-- Obras reales de la Municipalidad Distrital de La Victoria (Lima), tomadas de Infobras (Contraloría).
-- Consulta del 23 de noviembre de 2026. Fuente: https://infobras.contraloria.gob.pe
--
-- Qué hace:
--   1. Crea la municipalidad con slug 'la-victoria' solo si aún no existe (es un dato, no código).
--   2. Carga 59 obras: 46 publicadas y 13 sin publicar.
--
-- Criterios:
--   - Solo La Victoria de Lima. Infobras también tiene La Victoria de Chiclayo (Lambayeque): no se cargó.
--   - Publicadas: las 9 obras en ejecución y las finalizadas con fecha de término de 2024 en adelante.
--   - Sin publicar: finalizadas con término en 2022 y 2023, para que el personal decida.
--   - Quedan fuera las obras «Sin Ejecución» (la tabla solo admite en ejecución y finalizada), las
--     anteriores a 2022 y dos registros «en ejecución» desactualizados (códigos 10603 y 45337).
--   - avance_pct es el avance físico que reporta Infobras (0 si no lo reporta; la app no lo muestra
--     en finalizadas). En las obras en ejecución recientes Infobras aún no informa avance.
--   - monto_asignado es el monto de contrato de Infobras; 0 significa que no hay dato y la app no
--     lo muestra. monto_ejecutado queda en 0: Infobras no lo informa.
--   - Sin coordenadas: la obra sale en la lista, pero no en el mapa, hasta verificarlas.
--   - Sin fotos: Infobras es de la entidad ejecutora; solo se publican fotos con su permiso.
--
-- Requiere las columnas codigo_infobras y nombre_oficial (migración 20261123000001).
-- No crea tablas ni cambia políticas: obras ya tiene municipalidad_id y RLS.

insert into public.municipalidades (slug, nombre, zona)
values ('la-victoria', 'Municipalidad de La Victoria', 'Lima Centro')
on conflict (slug) do nothing;

insert into public.obras
  (municipalidad_id, codigo_infobras, nombre, nombre_corto, ubicacion, estado, avance_pct, meta,
   monto_asignado, monto_ejecutado, fotos, publicada, inicio, actualizada_en, hitos, nombre_oficial)
select m.id, v.codigo, v.nombre, v.nombre_corto, v.ubicacion, v.estado, v.avance, v.meta,
       v.monto, 0, 0, v.publicada, v.inicio::date, '2026-11-23', '[]'::jsonb, v.oficial
from public.municipalidades m
cross join (values
  (562416, 'Renovación del parque Changanaquí y Robert Kennedy', 'parque Changanaquí y Robert Kennedy', 'Calle Manuel Arrisueño', 'en_ejecucion', 0, 'dic 2026', 598545.65, true, '2026-10-24', 'RENOVACION DE VEREDA Y RAMPA; REPARACION DE ESPACIO DE RECREACION PASIVA; CONSTRUCCION DE SARDINEL; ADEMÁS DE OTROS ACTIVOS EN EL(LA) PARQUE CHANGANAQUI Y ROBERT KENNEDY EN EL CENTRO POBLADO LA VICTORIA, DISTRITO DE LA VICTORIA, PROVINCIA LIMA, DEPARTAMENTO LIMA'),
